// Cloudflare Email Decode - Dummy implementation for offline mode
(function(){
  function decodeEmail(encodedString) {
    var email = "", r = parseInt(encodedString.substr(0, 2), 16), n, i;
    for (n = 2; encodedString.length - n; n += 2) {
      i = parseInt(encodedString.substr(n, 2), 16) ^ r;
      email += String.fromCharCode(i);
    }
    return email;
  }
  
  function decodeEmails() {
    var encodedElements = document.querySelectorAll('a[data-cfemail]');
    for (var i = 0; i < encodedElements.length; i++) {
      var encoded = encodedElements[i].getAttribute('data-cfemail');
      if (encoded) {
        var decoded = decodeEmail(encoded);
        encodedElements[i].href = 'mailto:' + decoded;
        encodedElements[i].textContent = decoded;
      }
    }
  }
  
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', decodeEmails);
  } else {
    decodeEmails();
  }
})();
